<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Storage;
use Illuminate\Validation\Rule;
class AccountsController extends Controller {
 private function school(){ $u=auth()->user(); abort_unless($u->status && $u->school_id,403); return $u->school_id; }
 private function table($name){return DB::table($name)->where($name.'.school_id',$this->school());}
 private function years(){return $this->table('academic_years')->orderByDesc('start_date')->get();}
 private function filters(Request $r){$years=$this->years();$r->validate(['academic_year_id'=>'nullable|integer','from'=>'nullable|date_format:Y-m-d','to'=>'nullable|date_format:Y-m-d|after_or_equal:from']);$year=$r->academic_year_id?$years->firstWhere('id',(int)$r->academic_year_id):($years->firstWhere('is_current',1)??$years->first());abort_unless($year,422,'Select a valid school academic year.');$from=$r->from??$year->start_date;$to=$r->to??$year->end_date;abort_if($from>$to,422);return compact('years','year','from','to');}
 public function index(Request $r){extract($this->filters($r));$income=$this->table('fee_collections')->where('academic_year_id',$year->id)->where('status','posted')->whereBetween('payment_date',[$from,$to])->sum('total_amount');$expenses=$this->table('account_expenses')->where('academic_year_id',$year->id);$pending=(clone $expenses)->whereIn('status',['pending','approved'])->whereBetween('expense_date',[$from,$to])->sum('amount');$payments=$this->table('account_expense_payments')->join('account_expenses as e','e.id','=','account_expense_payments.expense_id')->where('e.school_id',$this->school())->where('e.academic_year_id',$year->id)->whereBetween('payment_date',[$from,$to]);$paid=(clone $payments)->sum('account_expense_payments.amount');$heads=(clone $payments)->join('account_expense_categories as c','c.id','=','e.category_id')->where('c.school_id',$this->school())->groupBy('c.name')->selectRaw('c.name, SUM(account_expense_payments.amount) as total')->get();$recent=(clone $payments)->select('account_expense_payments.*','e.payee')->orderByDesc('payment_date')->orderByDesc('account_expense_payments.id')->limit(8)->get();$vp=$this->table('account_vendor_payments')->join('account_vendor_invoices as vi','vi.id','=','account_vendor_payments.invoice_id')->where('vi.school_id',$this->school())->where('vi.academic_year_id',$year->id);$vendorPaid=(clone $vp)->whereBetween('payment_date',[$from,$to])->sum('account_vendor_payments.amount');$vendorDue=$this->table('account_vendor_invoices')->where('academic_year_id',$year->id)->whereIn('status',['approved','partial','paid'])->sum('amount')-(clone $vp)->sum('account_vendor_payments.amount');$salaryPaid=$this->table('account_salary_payments')->whereBetween('payment_date',[$from,$to])->sum('amount');$dues=$this->table('student_fee_dues')->where('academic_year_id',$year->id)->where('status',1);
 $feeSummary=(clone $dues)->selectRaw('COALESCE(SUM(payable_amount),0) demand, COALESCE(SUM(paid_amount),0) collected, COALESCE(SUM(balance_amount),0) outstanding')->first();
 $components=(clone $dues)->selectRaw('fee_head_name, SUM(payable_amount) demand, SUM(paid_amount) collected, SUM(balance_amount) outstanding')->groupBy('fee_head_name')->orderBy('fee_head_name')->get();
 $receipts=$this->table('fee_collections')->where('academic_year_id',$year->id)->where('status','posted')->whereBetween('payment_date',[$from,$to]);
 $salary=$this->table('account_salary_payments')->whereBetween('payment_date',[$from,$to]);
 $vendorPeriod=(clone $vp)->whereBetween('account_vendor_payments.payment_date',[$from,$to]);
 $monthly=function($q,$date,$amount){return (clone $q)->selectRaw("DATE_FORMAT($date,'%Y-%m') AS month_key, SUM($amount) AS total")->groupBy('month_key')->pluck('total','month_key');};
 $mi=$monthly($receipts,'payment_date','total_amount');$me=$monthly($payments,'account_expense_payments.payment_date','account_expense_payments.amount');$mv=$monthly($vendorPeriod,'account_vendor_payments.payment_date','account_vendor_payments.amount');$ms=$monthly($salary,'payment_date','amount');
 $trend=[];for($m=\Carbon\Carbon::parse($to)->startOfMonth()->subMonths(5)->max(\Carbon\Carbon::parse($from)->startOfMonth());$m->toDateString()<=$to;$m->addMonth()){$k=$m->format('Y-m');$trend[]=['label'=>$m->format('M Y'),'income'=>(float)($mi[$k]??0),'expense'=>(float)($me[$k]??0)+(float)($mv[$k]??0)+(float)($ms[$k]??0)];}
 $bankRows=DB::table('account_ledger_accounts as a')->leftJoin('account_journal_lines as l','l.account_id','=','a.id')->leftJoin('account_journals as j',function($join)use($to){$join->on('j.id','=','l.journal_id')->on('j.school_id','=','a.school_id')->where('j.status','posted')->where('j.entry_date','<=',$to);})->where('a.school_id',$this->school())->whereIn('a.type',['cash','bank'])->groupBy('a.id','a.name')->selectRaw('a.name, SUM(CASE WHEN j.id IS NOT NULL THEN l.debit-l.credit ELSE 0 END) balance')->get();
 $recentReceipts=(clone $receipts)->orderByDesc('payment_date')->orderByDesc('id')->limit(8)->get(['payment_date','receipt_no','total_amount']);
 return view('accounts.dashboard',compact('feeSummary','components','trend','bankRows','recentReceipts','salaryPaid','vendorPaid','vendorDue','years','year','from','to','income','pending','paid','heads','recent'));}
 public function categories(){return view('accounts.categories',['categories'=>$this->table('account_expense_categories')->orderBy('name')->get()]);}
 public function categoryStore(Request $r){$v=$r->validate(['name'=>['required','string','max:150',Rule::unique('account_expense_categories')->where('school_id',$this->school())]]);DB::table('account_expense_categories')->insert($v+['school_id'=>$this->school(),'created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Category added.');}
 public function expenses(Request $r){extract($this->filters($r));$categories=$this->table('account_expense_categories')->where('active',1)->orderBy('name')->get();$ledgerAccounts=$this->table('account_ledger_accounts')->whereIn('type',['expense','cash','bank'])->orderBy('name')->get();$daily=$this->table('account_expense_payments')->join('account_expenses as e','e.id','=','account_expense_payments.expense_id')->where('e.school_id',$this->school())->where('e.academic_year_id',$year->id)->whereBetween('payment_date',[$from,$to])->groupBy('payment_date')->selectRaw('payment_date, SUM(account_expense_payments.amount) total')->orderByDesc('payment_date')->get();$rows=$this->table('account_expenses')->join('account_expense_categories as c','c.id','=','account_expenses.category_id')->where('c.school_id',$this->school())->where('academic_year_id',$year->id)->whereBetween('expense_date',[$from,$to])->select('account_expenses.*','c.name as category')->orderByDesc('expense_date')->orderByDesc('account_expenses.id')->paginate(20)->withQueryString();return view('accounts.expenses',compact('years','year','from','to','categories','rows','ledgerAccounts','daily'));}
 public function store(Request $r){$v=$r->validate(['academic_year_id'=>['required',Rule::exists('academic_years','id')->where('school_id',$this->school())],'category_id'=>['required',Rule::exists('account_expense_categories','id')->where('school_id',$this->school())->where('active',1)],'expense_date'=>'required|date_format:Y-m-d|before_or_equal:today','payee'=>'required|string|max:255','amount'=>'required|numeric|decimal:0,2|min:0.01|max:9999999999.99','description'=>'required|string|max:4000','invoice_reference'=>'nullable|string|max:255','payment_mode'=>'required|in:cash,upi,bank_transfer,cheque,card,other','reference'=>'nullable|string|max:255','expense_account_id'=>'required|integer','payment_account_id'=>'required|integer','invoice_file'=>'nullable|file|max:20480|mimes:pdf,doc,docx,xls,xlsx,csv,txt,jpg,jpeg,png,webp,gif,tif,tiff,bmp,heic,zip,odt,ods']);$year=$this->years()->firstWhere('id',(int)$v['academic_year_id']);abort_unless($year && $v['expense_date'] >= $year->start_date && $v['expense_date'] <= $year->end_date,422,'Expense date must fall in selected academic year.');$file=$r->file('invoice_file'); $payment=collect($v)->only(['payment_mode','reference','expense_account_id','payment_account_id'])->all();unset($v['invoice_file'],$v['payment_mode'],$v['reference'],$v['expense_account_id'],$v['payment_account_id']);$path=null;
  try {
   if($file){$path=$file->store('expense-invoices/'.$this->school(),'local');if(!$path){throw new \RuntimeException('Invoice upload failed.');}$v['invoice_path']=$path;$v['invoice_name']=mb_substr(basename(str_replace('\\','/',$file->getClientOriginalName())),0,255);}
   DB::transaction(function() use ($v,$payment){
    $accounts=$this->table('account_ledger_accounts')->whereIn('id',[$payment['expense_account_id'],$payment['payment_account_id']])->lockForUpdate()->get()->keyBy('id');
    $debit=$accounts->get($payment['expense_account_id']);$credit=$accounts->get($payment['payment_account_id']);
    abort_unless($debit && $debit->type==='expense' && $credit && $credit->type===($payment['payment_mode']==='cash'?'cash':'bank'),422,'Select an expense ledger and the correct cash/bank ledger.');
    $id=DB::table('account_expenses')->insertGetId($v+['school_id'=>$this->school(),'created_by'=>auth()->id(),'status'=>'paid','created_at'=>now(),'updated_at'=>now()]);
    $pid=DB::table('account_expense_payments')->insertGetId(['school_id'=>$this->school(),'expense_id'=>$id,'payment_date'=>$v['expense_date'],'amount'=>$v['amount'],'payment_mode'=>$payment['payment_mode'],'reference'=>$payment['reference']??null,'paid_by'=>auth()->id(),'created_at'=>now(),'updated_at'=>now()]);
    $jid=DB::table('account_journals')->insertGetId(['school_id'=>$this->school(),'entry_date'=>$v['expense_date'],'kind'=>'payment','description'=>mb_substr('Expense #'.$id.' - '.$v['payee'],0,255),'status'=>'posted','created_by'=>auth()->id(),'source'=>'expense_payment','source_id'=>$pid,'created_at'=>now(),'updated_at'=>now()]);
    DB::table('account_journal_lines')->insert([['journal_id'=>$jid,'account_id'=>$debit->id,'debit'=>$v['amount'],'credit'=>0],['journal_id'=>$jid,'account_id'=>$credit->id,'debit'=>0,'credit'=>$v['amount']]]);
   });
  } catch(\Throwable $ex){if($path){Storage::disk('local')->delete($path);}throw $ex;}
  return back()->with('success','Expense saved and posted to ledger.');}
 public function invoice($id){$e=$this->table('account_expenses')->where('id',$id)->first();abort_unless($e && $e->invoice_path && Storage::disk('local')->exists($e->invoice_path),404);return Storage::disk('local')->download($e->invoice_path,$e->invoice_name ?: 'invoice',['X-Content-Type-Options'=>'nosniff','Content-Type'=>'application/octet-stream']);}
 public function pay(Request $r,$id){$v=$r->validate(['payment_date'=>'required|date_format:Y-m-d|before_or_equal:today','payment_mode'=>'required|in:cash,upi,bank_transfer,cheque,card,other','reference'=>'required_unless:payment_mode,cash|nullable|string|max:255']);DB::transaction(function()use($v,$id){$e=$this->table('account_expenses')->where('id',$id)->lockForUpdate()->first();abort_unless($e,404);abort_unless($e->status==='approved' && $v['payment_date'] >= $e->expense_date,422,'Expense must be approved and payment cannot precede expense.');DB::table('account_expense_payments')->insert($v+['school_id'=>$this->school(),'expense_id'=>$e->id,'amount'=>$e->amount,'paid_by'=>auth()->id(),'created_at'=>now(),'updated_at'=>now()]);$this->table('account_expenses')->where('id',$id)->update(['status'=>'paid','updated_at'=>now()]);});return back()->with('success','Payment recorded.');}
 public function voucher($id){$expense=$this->table('account_expenses')->where('id',$id)->first();abort_unless($expense,404);$payment=$this->table('account_expense_payments')->where('expense_id',$id)->first();abort_unless($payment,404);$school=DB::table('schools')->where('id',$this->school())->first();return view('accounts.voucher',compact('expense','payment','school'));}
}
